create extension if not exists "pgcrypto";create type class_kind as enum ('physical','magical');create type visibility_kind as enum ('private','shared','published');create table users(id uuid primary key default gen_random_uuid(),email text not null unique,display_name text not null,created_at timestamptz not null default now());create table content_items(id uuid primary key default gen_random_uuid(),type text not null,name text not null,visibility visibility_kind not null default 'private',owner_id uuid references users(id),version integer not null default 1,payload jsonb not null default '{}',created_at timestamptz not null default now());create table characters(id uuid primary key default gen_random_uuid(),owner_id uuid not null references users(id),name text not null,level smallint not null check(level between 1 and 20),race_id uuid references content_items(id),class_id uuid references content_items(id),community_id uuid references content_items(id),state jsonb not null default '{}',created_at timestamptz not null default now());create table character_content(character_id uuid references characters(id) on delete cascade,content_id uuid references content_items(id),kind text not null,rank integer,primary key(character_id,content_id,kind));create table character_resources(id uuid primary key default gen_random_uuid(),character_id uuid not null references characters(id) on delete cascade,resource text not null,delta integer not null,reason text not null,created_at timestamptz not null default now());create table campaigns(id uuid primary key default gen_random_uuid(),name text not null,description text,master_id uuid not null references users(id),created_at timestamptz not null default now());create table campaign_members(campaign_id uuid references campaigns(id) on delete cascade,user_id uuid references users(id),role text not null,primary key(campaign_id,user_id));create table sessions(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id) on delete cascade,name text not null,started_at timestamptz,ended_at timestamptz);create table encounters(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id) on delete cascade,name text not null,state jsonb not null default '{}');create index content_search_idx on content_items using gin (to_tsvector('portuguese',name || ' ' || coalesce(payload->>'description','')));
